-- Professions module: leveling plans built from the WoW Forever guides on wow-professions.com
-- (Data.lua, generated by tools/build_professions.py), and a shopping list for their materials.
-- Buyer.lua works through the list at the auction house.
--
-- Materials are tracked by name: the guides don't give item IDs. IDs are learned from Stash and
-- from auction house searches, and kept in db.itemIDs.

local _, CF = ...
local W = CF.W
local C, GREY, GREEN, YELLOW = W.C, W.GREY, W.GREEN, W.YELLOW

local M = CF:NewModule("professions", {
    title = "Professions",
    description = "Leveling plans from wow-professions.com, and a shopping list the auction house buys for you.",
    defaults = {
        list = {},          -- [material name] = how many to buy
        itemIDs = {},       -- [material name] = item ID
        popup = true,       -- open the buyer when the auction house opens
        useStash = true,    -- count what your other characters hold
        buyerPos = nil,     -- { point, x, y }
    },
    charDefaults = {
        prof = "leatherworking",
        from = 1,
        to = 75,
        choices = {},       -- [prof][step index] = alternative picked instead of the main recipe
    },
})

local GUIDES = CF.ProfessionGuides
local PROF_ORDER = { "alchemy", "blacksmithing", "cooking", "enchanting", "engineering", "firstaid", "leatherworking", "tailoring" }

-- Sold by trade-goods and reagent vendors without limit, so never bought on the auction house.
M.VENDOR = {}
for _, name in ipairs({
    "Coarse Thread", "Fine Thread", "Silken Thread", "Heavy Silken Thread", "Rune Thread",
    "Bleach", "Black Dye", "Blue Dye", "Gray Dye", "Orange Dye", "Pink Dye", "Purple Dye", "Red Dye", "Yellow Dye",
    "Empty Vial", "Leaded Vial", "Crystal Vial", "Imbued Vial",
    "Weak Flux", "Strong Flux", "Coal",
    "Salt", "Mild Spices", "Hot Spices", "Soothing Spices", "Refreshing Spring Water", "Ice Cold Milk",
    "Copper Rod", "Simple Wood", "Wooden Stock", "Heavy Stock", "Maple Seed", "Stranglethorn Seed",
}) do M.VENDOR[name] = true end

local function Print(msg) CF.Print(msg, "Professions") end

---------------------------------------------------------------------------
-- Items and what you own
---------------------------------------------------------------------------
function M.ItemID(name)
    local id = M.db.itemIDs[name]
    if id then return id end
    id = C_Item.GetItemInfoInstant(name)
    if id then M.db.itemIDs[name] = id end
    return id
end

function M.LearnID(name, id)
    M.db.itemIDs[name] = id
end

local function StashModule()
    local s = CF.modules.stash
    return M.db.useStash and s and s.running and s.CountByName and s
end

-- On every character Stash counts when that's on, else this character's bags and bank.
function M.Owned(name)
    local stash = StashModule()
    if stash then
        local n, id = stash.CountByName(name)
        if id then M.LearnID(name, id) end
        return n
    end
    local id = M.ItemID(name)
    return id and C_Item.GetItemCount(id, true) or 0
end

---------------------------------------------------------------------------
-- Plans
---------------------------------------------------------------------------
local function Choices(prof)
    local c = M.char.choices
    c[prof] = c[prof] or {}
    return c[prof]
end

local function StepRecipes(step, alt)
    if alt and step.alts and step.alts[alt] then return step.alts[alt].recipes end
    return step.main
end

local function Up(x) return math.ceil(x - 0.001) end

-- Everything needed to go from skill `from` to `to`:
--   crafts: { lo, hi, step, stepIndex, recipe, n, alt } in guide order, then extra crafts for
--           materials you have to make (made = true)
--   mats:   { name, need, have, make, buy, vendor }
--   ranks:  training notes for the skill caps the range crosses
function M.Plan(prof, from, to)
    local g = GUIDES[prof]
    local choices = Choices(prof)
    local crafts, need, made = {}, {}, {}

    for i, s in ipairs(g.steps) do
        local overlap = math.min(s.hi, to) - math.max(s.lo, from)
        if overlap > 0 then
            local frac = overlap / math.max(1, s.hi - s.lo)
            for _, r in ipairs(StepRecipes(s, choices[i])) do
                local n = Up(r.count * frac)
                crafts[#crafts + 1] = { lo = math.max(s.lo, from), hi = math.min(s.hi, to), step = s,
                    stepIndex = i, recipe = r, n = n, alt = choices[i] }
                made[r.name] = (made[r.name] or 0) + n
                for _, m in ipairs(r.mats) do
                    need[m[1]] = (need[m[1]] or 0) + m[2] / r.count * n
                end
            end
        end
    end

    -- Materials the guide makes earlier (Cured Heavy Hide, bolts of cloth): use what you have,
    -- and plan to make the rest from their own materials.
    local have, toMake = {}, {}
    local function Have(name)
        if have[name] == nil then have[name] = M.Owned(name) end
        return have[name]
    end
    for _ = 1, 4 do
        for name, recipe in pairs(g.made) do
            if need[name] then
                local short = Up(need[name]) - (made[name] or 0) - Have(name) - (toMake[name] or 0)
                if short > 0 then
                    toMake[name] = (toMake[name] or 0) + short
                    for _, m in ipairs(recipe.mats) do
                        need[m[1]] = (need[m[1]] or 0) + m[2] * short
                    end
                end
            end
        end
    end
    for name, n in pairs(toMake) do
        crafts[#crafts + 1] = { made = true, n = n, recipe = { name = name, spell = g.made[name].spell } }
    end

    local mats = {}
    for name, q in pairs(need) do
        local total = Up(q)
        local make = (made[name] or 0) + (toMake[name] or 0)
        local h = Have(name)
        mats[#mats + 1] = { name = name, need = total, have = h, make = make,
            buy = math.max(0, total - make - h), vendor = M.VENDOR[name] }
    end
    table.sort(mats, function(a, b)
        if (a.vendor or false) ~= (b.vendor or false) then return not a.vendor end
        if (a.buy > 0) ~= (b.buy > 0) then return a.buy > 0 end
        return a.name < b.name
    end)

    local ranks = {}
    for _, r in ipairs(g.ranks) do
        if r.at >= from and r.at < to then ranks[#ranks + 1] = r end
    end
    return { crafts = crafts, mats = mats, ranks = ranks }
end

---------------------------------------------------------------------------
-- Shopping list
---------------------------------------------------------------------------
function M.AddToList(mats)
    local items, units = 0, 0
    for _, m in ipairs(mats) do
        if m.buy > 0 then
            M.db.list[m.name] = (M.db.list[m.name] or 0) + m.buy
            items, units = items + 1, units + m.buy
        end
    end
    return items, units
end

function M.Bought(name, n)
    local left = (M.db.list[name] or 0) - n
    M.db.list[name] = left > 0 and left or nil
    CF.RefreshCurrent()
end

-- Auction house items still to buy, in name order: { name, qty }
function M.BuyQueue()
    local q = {}
    for name, n in pairs(M.db.list) do
        if n > 0 and not M.VENDOR[name] then q[#q + 1] = { name = name, qty = n } end
    end
    table.sort(q, function(a, b) return a.name < b.name end)
    return q
end

---------------------------------------------------------------------------
-- Your current skill
---------------------------------------------------------------------------
local function CurrentSkill(profName)
    if GetProfessions and GetProfessionInfo then
        local list = { GetProfessions() }
        for i = 1, 6 do
            if list[i] then
                local name, _, rank = GetProfessionInfo(list[i])
                if name == profName then return rank end
            end
        end
    end
    if GetNumSkillLines and GetSkillLineInfo then
        for i = 1, GetNumSkillLines() do
            local name, isHeader, _, rank = GetSkillLineInfo(i)
            if not isHeader and name == profName then return rank end
        end
    end
end

---------------------------------------------------------------------------
-- Slash: /cf professions ...
---------------------------------------------------------------------------
function M:slash(msg)
    local cmd = strtrim(msg or ""):lower()
    if cmd == "" or cmd == "plan" then
        CF.Open("professions", "plan")
    elseif cmd == "list" then
        CF.Open("professions", "list")
    elseif cmd == "buy" then
        if not M.OpenBuyer() then Print("open the auction house first, with something on your shopping list.") end
    else
        Print("commands:")
        print("   /cf professions  - plan a skill range")
        print("   /cf professions list  - your shopping list")
        print("   /cf professions buy  - open the buyer at the auction house")
    end
end

function M:OnLogin()
    M.StartBuyer()
end

---------------------------------------------------------------------------
-- Plan page
---------------------------------------------------------------------------
local STEP_COLS = { { 52 }, { 190 } }
local MAT_COLS = { { 120 }, { 32, "RIGHT" }, { 32, "RIGHT" }, { 36, "RIGHT" } }
local LIST_ROWS = 11

local function ProfButtons(p)
    p.profButtons = {}
    local x, y = 0, 0
    for _, key in ipairs(PROF_ORDER) do
        local b = W.Button(p, GUIDES[key].name, 10, 22, function()
            M.char.prof = key
            local skill = CurrentSkill(GUIDES[key].name)
            if skill then
                M.char.from = skill
                M.char.to = math.min(GUIDES[key].max, skill + 25)
            end
            CF.RefreshCurrent()
        end)
        local w = math.ceil(b.text:GetStringWidth()) + 18
        b:SetWidth(w)
        if x + w > 540 then x, y = 0, y - 26 end
        b:SetPoint("TOPLEFT", x, y)
        x = x + w + 4
        b.bar = W.AccentTexture(b)
        b.bar:SetHeight(2)
        b.bar:SetPoint("BOTTOMLEFT", 1, 1)
        b.bar:SetPoint("BOTTOMRIGHT", -1, 1)
        b.key = key
        p.profButtons[#p.profButtons + 1] = b
    end
    return y - 26
end

local function SkillBox(p, onSet)
    local e = W.EditBox(p, 48, "", nil)
    e:SetNumeric(true)
    e:SetMaxLetters(3)
    e:SetJustifyH("CENTER")
    local function Commit(self)
        local v = tonumber(self:GetText())
        if v then onSet(v) end
        self:ClearFocus()
        CF.RefreshCurrent()
    end
    e:SetScript("OnEnterPressed", Commit)
    e:SetScript("OnEditFocusLost", Commit)
    return e
end

local function Clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

local function BuildPlan(p)
    local top = ProfButtons(p)

    local fromLabel = W.Text(p, 12)
    fromLabel:SetPoint("TOPLEFT", 0, top - 8)
    fromLabel:SetText("From")
    p.from = SkillBox(p, function(v) M.char.from = v end)
    p.from:SetPoint("LEFT", fromLabel, "RIGHT", 8, 0)
    local toLabel = W.Text(p, 12)
    toLabel:SetPoint("LEFT", p.from, "RIGHT", 10, 0)
    toLabel:SetText("to")
    p.to = SkillBox(p, function(v) M.char.to = v end)
    p.to:SetPoint("LEFT", toLabel, "RIGHT", 8, 0)
    p.mine = W.Button(p, "My skill", 70, 22, function()
        local skill = CurrentSkill(GUIDES[M.char.prof].name)
        if skill then
            M.char.from = skill
        else
            Print("you don't have " .. GUIDES[M.char.prof].name .. " on this character.")
        end
        CF.RefreshCurrent()
    end)
    p.mine:SetPoint("LEFT", p.to, "RIGHT", 10, 0)

    p.add = W.Button(p, "Add to shopping list", 150, 24, function()
        if not p.plan then return end
        local items, units = M.AddToList(p.plan.mats)
        if items == 0 then
            Print("nothing to buy: you already have everything for this range.")
        else
            Print(("added %d item%s (%d in total) to your shopping list."):format(items, items == 1 and "" or "s", units))
        end
        CF.RefreshCurrent()
    end)
    p.add:SetPoint("TOPRIGHT", 0, top - 6)

    local listTop = top - 44
    local h1 = W.ListHeader(p, STEP_COLS, { "Skill", "Craft  (click to switch recipe)" })
    h1:SetPoint("TOPLEFT", 0, listTop)
    h1:SetWidth(262)
    p.steps = W.List(p, STEP_COLS, 18, LIST_ROWS)
    p.steps:SetPoint("TOPLEFT", 0, listTop - 20)
    p.steps:SetWidth(262)

    local h2 = W.ListHeader(p, MAT_COLS, { "Material", "Need", "Have", "Buy" })
    h2:SetPoint("TOPLEFT", 280, listTop)
    h2:SetPoint("RIGHT")
    p.mats = W.List(p, MAT_COLS, 18, LIST_ROWS)
    p.mats:SetPoint("TOPLEFT", 280, listTop - 20)
    p.mats:SetPoint("RIGHT")

    p.note = W.Text(p, 11, 0.7, 0.7, 0.7)
    p.note:SetPoint("TOPLEFT", 0, listTop - 20 - LIST_ROWS * 18 - 8)
    p.note:SetPoint("RIGHT")
    p.note:SetWordWrap(true)
    p.note:SetJustifyV("TOP")
end

local function StepTip(c)
    return function(tt)
        tt:AddLine(c.recipe.name, 1, 1, 1)
        if c.made then
            tt:AddLine("A material for later steps that you don't have enough of.", 0.8, 0.8, 0.8, true)
            return
        end
        local mats = {}
        for _, m in ipairs(c.recipe.mats) do mats[#mats + 1] = Up(m[2] / c.recipe.count * c.n) .. " " .. m[1] end
        tt:AddLine(table.concat(mats, ", "), 0.8, 0.8, 0.8, true)
        local notes = c.step.notes
        if notes then for _, n in ipairs(notes) do tt:AddLine(n, 0.6, 0.8, 1, true) end end
        local alts = c.step.alts
        if alts then
            tt:AddLine(" ")
            tt:AddLine(c.alt and "Using an alternative. Click to switch." or "Click to use the alternative:", 1, 0.82, 0)
            for i, a in ipairs(alts) do
                local names = {}
                for _, r in ipairs(a.recipes) do names[#names + 1] = r.name end
                tt:AddLine((c.alt == i and "> " or "- ") .. table.concat(names, ", ") .. ": " .. a.note, 0.8, 0.8, 0.8, true)
            end
        end
    end
end

local function NextChoice(prof, c)
    local choices = Choices(prof)
    local n = #c.step.alts
    local cur = choices[c.stepIndex] or 0
    choices[c.stepIndex] = (cur < n) and (cur + 1) or nil
end

local function MatRow(m)
    local buy
    if m.buy > 0 then
        buy = m.vendor and C(YELLOW, m.buy) or tostring(m.buy)
    elseif m.make > 0 and m.have < m.need then
        buy = C(GREEN, "craft")
    else
        buy = C(GREY, "-")
    end
    local id = M.ItemID(m.name)
    return {
        cols = { m.name, tostring(m.need), tostring(m.have), buy },
        itemID = id,
        tip = not id and function(tt)
            tt:AddLine(m.name, 1, 1, 1)
            if m.vendor then tt:AddLine("Sold by trade-goods vendors.", 0.8, 0.8, 0.8) end
            if m.make > 0 then tt:AddLine("You'll craft " .. m.make .. " of these.", 0.8, 0.8, 0.8) end
        end or nil,
    }
end

local function RefreshPlan(p)
    local prof = M.char.prof
    local g = GUIDES[prof]
    if not g then
        prof = "leatherworking"
        M.char.prof, g = prof, GUIDES[prof]
    end
    for _, b in ipairs(p.profButtons) do
        local on = b.key == prof
        b.bar:SetShown(on)
        local c = on and 1 or 0.55
        b.text:SetTextColor(c, c, c)
    end
    local from = Clamp(M.char.from or 1, 1, g.max)
    local to = Clamp(M.char.to or g.max, from, g.max)
    M.char.from, M.char.to = from, to
    if not p.from:HasFocus() then p.from:SetText(from) end
    if not p.to:HasFocus() then p.to:SetText(to) end

    local plan = M.Plan(prof, from, to)
    p.plan = plan

    local rows = {}
    for _, c in ipairs(plan.crafts) do
        local skill = c.made and C(GREY, "make") or (c.lo .. "-" .. c.hi)
        local name = c.n .. "x " .. c.recipe.name
        if c.alt then name = C(YELLOW, name) end
        rows[#rows + 1] = {
            cols = { skill, name },
            mark = c.alt ~= nil,
            tip = StepTip(c),
            onClick = (not c.made and c.step.alts) and function()
                NextChoice(prof, c)
                CF.RefreshCurrent()
            end or nil,
        }
    end
    p.steps:SetData(rows, from >= to and "Pick a higher target skill." or "No steps in this range.")

    local matRows = {}
    for _, m in ipairs(plan.mats) do matRows[#matRows + 1] = MatRow(m) end
    p.mats:SetData(matRows, "")

    local notes = {}
    for _, r in ipairs(plan.ranks) do notes[#notes + 1] = C(YELLOW, r.title .. ": ") .. r.text end
    if #notes == 0 then
        notes[1] = C(GREY, (StashModule() and "Have counts every character Stash knows. " or "")
            .. "Yellow Buy numbers are sold by vendors. Craft counts are estimates from the guide.")
    end
    p.note:SetText(table.concat(notes, "\n"))
end

---------------------------------------------------------------------------
-- Shopping list page
---------------------------------------------------------------------------
local LIST_COLS = { { 240 }, { 50, "RIGHT" }, { 50, "RIGHT" }, { 140 } }

local function BuildList(p)
    local hdr = W.ListHeader(p, LIST_COLS, { "Item", "Buy", "Have", "Where" })
    hdr:SetPoint("TOPLEFT", 0, 0)
    hdr:SetPoint("RIGHT")
    p.list = W.List(p, LIST_COLS, 20, 13)
    p.list:SetPoint("TOPLEFT", 0, -20)
    p.list:SetPoint("RIGHT")

    p.amount = W.EditBox(p, 60, "Amount", nil)
    p.amount:SetNumeric(true)
    p.amount:SetMaxLetters(5)
    p.amount:SetPoint("BOTTOMLEFT", 0, 0)
    p.amount:SetScript("OnEnterPressed", function(self)
        local v = tonumber(self:GetText())
        if p.selected and v then M.db.list[p.selected] = v > 0 and v or nil end
        self:SetText("")
        self:ClearFocus()
        CF.RefreshCurrent()
    end)
    W.Tooltip(p.amount, "Type a new amount for the selected item and press Enter.")

    p.remove = W.Button(p, "Remove", 80, 24, function()
        if p.selected then M.db.list[p.selected] = nil; p.selected = nil end
        CF.RefreshCurrent()
    end)
    p.remove:SetPoint("LEFT", p.amount, "RIGHT", 6, 0)
    p.clear = W.Button(p, "Clear list", 80, 24, function()
        if IsShiftKeyDown() then
            wipe(M.db.list)
            p.selected = nil
            CF.RefreshCurrent()
        else
            Print("shift-click Clear list to empty your shopping list.")
        end
    end)
    p.clear:SetPoint("LEFT", p.remove, "RIGHT", 6, 0)
    p.buy = W.Button(p, "Buy at auction house", 160, 24, function()
        if not M.OpenBuyer() then Print("open the auction house first.") end
    end)
    p.buy:SetPoint("BOTTOMRIGHT", 0, 0)
end

local function RefreshList(p)
    local rows, names = {}, {}
    for name in pairs(M.db.list) do names[#names + 1] = name end
    table.sort(names, function(a, b)
        if (M.VENDOR[a] or false) ~= (M.VENDOR[b] or false) then return not M.VENDOR[a] end
        return a < b
    end)
    for _, name in ipairs(names) do
        local vendor = M.VENDOR[name]
        rows[#rows + 1] = {
            cols = { name, tostring(M.db.list[name]), tostring(M.Owned(name)),
                vendor and C(YELLOW, "vendor") or "auction house" },
            itemID = M.ItemID(name),
            mark = name == p.selected,
            onClick = function() p.selected = name; CF.RefreshCurrent() end,
        }
    end
    if p.selected and not M.db.list[p.selected] then p.selected = nil end
    p.list:SetData(rows, "Your shopping list is empty. Add a plan from the Plan tab.")
    p.remove:SetAlpha(p.selected and 1 or 0.4)
    p.buy:SetAlpha(M.AuctionHouseOpen() and #M.BuyQueue() > 0 and 1 or 0.4)
end

---------------------------------------------------------------------------
-- Settings page
---------------------------------------------------------------------------
local function BuildSettings(p)
    local db = M.db
    W.Header(p, "Shopping list"):SetPoint("TOPLEFT", 0, 0)
    p.items = {
        W.Check(p, "Open the buyer when the auction house opens", function() return db.popup end,
            function(v) db.popup = v end, "Only when there's something on your list to buy there."),
        W.Check(p, "Count items on all your characters (Stash)", function() return db.useStash end,
            function(v) db.useStash = v end,
            "Uses the Stash module's counts, so you don't buy what an alt already has. Off: this character's bags and bank only."),
    }
    for i, w in ipairs(p.items) do
        w:SetWidth(400)
        w:SetPoint("TOPLEFT", 0, -24 - (i - 1) * 24)
    end

    W.Header(p, "About"):SetPoint("TOPLEFT", 0, -96)
    local t = W.Text(p, 12, 0.7, 0.7, 0.7)
    t:SetPoint("TOPLEFT", 0, -120)
    t:SetWidth(520)
    t:SetWordWrap(true)
    t:SetText("Plans follow the WoW Forever leveling guides on wow-professions.com. Craft counts are the "
        .. "guide's estimates, so you may need a few more or fewer.\n\n"
        .. "Where the guide offers other recipes (or lets you pick from a table, like Cooking), click a step on the "
        .. "Plan tab to switch. Cooking plans start at 50.\n\n"
        .. "If you also use Naowh Forever, turn off its Shopping List in its Professions settings, so two buyers "
        .. "don't open at the auction house.")
end

local function RefreshSettings(p)
    for _, w in ipairs(p.items) do w.Refresh() end
end

M.pages = {
    { key = "plan",     label = "Plan",          build = BuildPlan,     refresh = RefreshPlan },
    { key = "list",     label = "Shopping list", build = BuildList,     refresh = RefreshList },
    { key = "settings", label = "Settings",      build = BuildSettings, refresh = RefreshSettings },
}
